from collections.abc import Mapping
from copy import deepcopy


class WorkMessage:
    def __init__(self, kind, fields):
        self._validate(kind, fields)
        self._kind = kind
        self._fields = deepcopy(fields)

    @property
    def kind(self):
        return self._kind

    @property
    def fields(self):
        return deepcopy(self._fields)

    def is_consistent(self):
        try:
            self._validate(self._kind, self._fields)
        except (TypeError, ValueError):
            return False
        return True

    @staticmethod
    def _validate(kind, fields):
        if kind != "job" and kind != "reply":
            raise ValueError("unknown kind")
        if not isinstance(fields, Mapping):
            raise TypeError("fields must be a mapping")

        required = (
            {"id", "priority", "tags"}
            if kind == "job"
            else {"id", "accepted"}
        )
        if set(fields) != required:
            raise ValueError("incorrect fields")
        if not isinstance(fields["id"], str):
            raise TypeError("id must be a string")
        if not fields["id"]:
            raise ValueError("id must not be empty")

        if kind == "job":
            priority = fields["priority"]
            if isinstance(priority, bool) or not isinstance(priority, int):
                raise TypeError("priority must be an integer")
            if not 0 <= priority <= 9:
                raise ValueError("priority out of range")
            tags = fields["tags"]
            if not isinstance(tags, list):
                raise TypeError("tags must be a list")
            if any(not isinstance(tag, str) for tag in tags):
                raise TypeError("tags must contain strings")
            if any(not tag for tag in tags) or len(set(tags)) != len(tags):
                raise ValueError("tags must be non-empty and unique")
        elif type(fields["accepted"]) is not bool:
            raise TypeError("accepted must be a boolean")
